async <T = unknown>(
  sqlQuery: string,
  cwdWorker: string,
): Promise<T> => {
  const child = spawn(
    './node_modules/.bin/wrangler',
    ['d1', 'execute', 'TAON_D1', '--remote', '--json', '--command', sqlQuery],
    {
      cwd: cwdWorker,
      shell: false,
      stdio: 'pipe',
      env: {
        ...process.env,
        CI: 'true',
        NO_COLOR: '1',
        FORCE_COLOR: '0',
      },
    },
  );

  let stdout = '';
  let stderr = '';

  child.stdout.setEncoding('utf8');
  child.stderr.setEncoding('utf8');

  child.stdout.on('data', chunk => {
    stdout += chunk;
  });

  child.stderr.on('data', chunk => {
    stderr += chunk;
  });

  const exitCode = await new Promise<number>((resolve, reject) => {
    child.once('error', reject);

    // 'close' ensures stdout/stderr streams have finished.
    child.once('close', code => resolve(code ?? -1));
  });

  if (exitCode !== 0) {
    throw new Error(
      `Wrangler failed (exit code ${exitCode})\n` +
        `STDOUT:\n${stdout}\nSTDERR:\n${stderr}`,
    );
  }

  const result = parseJsonText<T>(stdout);

  if (typeof result === 'string') {
    throw new Error(`Wrangler did not return valid JSON:\n${stdout}`);
  }

  return result;
}

