src/lib/project/cli/cli-MIGRATION.ts#all.value:
Helpers.getFilesFrom(
        this.project.pathFor([srcMainProject, migrationsFromLib]),
        {
          recursive: true,
        },
      )
        .filter(f => {
          const timestampRegex = /\d{13}/;
          return f.endsWith('.ts') && timestampRegex.test(f);
        })
        .map(f => {
          let timestamp: number;
          try {
            timestamp = Number(path.basename(f).match(/\d{13}/)[0]);
          } catch (error) {
            return;
          }
          if (!UtilsMigrations.isValidTimestamp(timestamp)) {
            return;
          }

          return {
            timestamp,
            name: _.startCase(
              path.basename(f).replace(`${timestamp}`, '').replace('.ts', ''),
            ),
          };
        })
        .filter(f => !!f)
        .map(f => {
          return {
            name: `(${f.timestamp}) ${UtilsMigrations.formatTimestamp(f.timestamp)}  [${f.name}]`,
            value: f.timestamp,
          };
        })
        .sort((a, b) => {
          return b.value - a.value;
        })

