          flushPending();

          const wrapper = $(node);
          const children = wrapper.contents().toArray();

          wrapper.empty();
          block.append(wrapper);

          splitIntoTranslatableSpans(node);

          return;
        }

        pendingNodes.push(node);
      };

      originalNodes.forEach(appendNode);
      flushPending();
    }

