src/lib/app-utils.ts#pingUrl.value:
async (
  url: string,
  context: string,
  reason = 'No able to ping after depoy',
) => {
  if (!url.startsWith('http')) {
    url = `https://${url}`;
  }
  const task = Helpers.actionStarted(
    `Pinging ${url}/${apiPrefix}/${context ? context + '/tcp/' : ''}`,
  );
  try {
    const res = await fetch(url);
    const pingResponse = await res.text();
    Helpers.logInfo(`Ping response:${pingResponse}`);
    task.done();
  } catch (error) {
    config.frameworkName === 'tnp' && console.error(error);
    Helpers.error(reason, false, true);
  }
}

src/lib/app-utils.ts#processDirectory.value:
(dirPath: string): void => {
    for (const entry of fse.readdirSync(dirPath, { withFileTypes: true })) {
      const fullPath = path.join(dirPath, entry.name);

      if (entry.isDirectory()) {
        processDirectory(fullPath);
        continue;
      }

      const ext = path.extname(entry.name);
      const readonlyHeader = commentsByExt[ext];

      if (!readonlyHeader) {
        continue;
      }

      let content = UtilsFilesFoldersSync.readFile(fullPath);

      if (ext === '.ts') {
        content =
          `// @ts-` +
          `nocheck\n${readonlyHeader}${UtilsTypescript.minifyTypescriptSource(content)}`;
      } else if (ext === '.scss') {
        content = `${readonlyHeader}${removeScssComments(content)}`;
      } else if (ext === '.html') {
        content = `${readonlyHeader}${removeHtmlComments(content)}`;
      }

      UtilsFilesFoldersSync.writeFile(fullPath, content);
    }
  }

